 * Cell address parsing and ordering helpers shared by the sheet reader, the
 * formula evaluator and the deps walker.
 */

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/**
 * Parses a raw address token (case-insensitive) into its canonical column
 * number, row number and printable key, or returns null when the token is
 * not shaped like an address or names a row below 1.
 */
export function parseAddressToken(raw) {
  const m = ADDRESS_RE.exec(raw)
  if (!m) return null
  const letters = m[1].toUpperCase()
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  const col =
    letters.length === 1
      ? letters.charCodeAt(0) - 64
      : (letters.charCodeAt(0) - 64) * 26 + (letters.charCodeAt(1) - 64)
  return { col, row, key: `${letters}${row}` }
}

/** Converts a 1-based column number back into its one or two letter name. */
export function colToLetters(n) {
  if (n <= 26) return String.fromCharCode(64 + n)
  const first = Math.floor((n - 1) / 26)
  const second = ((n - 1) % 26) + 1
  return String.fromCharCode(64 + first) + String.fromCharCode(64 + second)
}

/** Ascending column-then-row comparator for address-like `{col, row}` records. */
export function compareAddress(a, b) {
  return a.col - b.col || a.row - b.row
}
"}

