 * not grammatically valid; it never throws for malformed input.
 */

const TWO_CHAR_OPS = ['<=', '>=', '<>']
const ONE_CHAR_OPS = '=<>+-*/^(),:'
const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

function tokenize(src) {
  const tokens = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') {
      i++
      continue
    }
    if (c >= '0' && c <= '9') {
      let j = i
      while (j < src.length && src[j] >= '0' && src[j] <= '9') j++
      if (src[j] === '.') {
        if (!(src[j + 1] >= '0' && src[j + 1] <= '9')) throw new Error('bad number')
        j++
        while (j < src.length && src[j] >= '0' && src[j] <= '9') j++
      }
      tokens.push({ type: 'NUM', value: Number(src.slice(i, j)) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(c)) {
      let j = i + 1
      while (j < src.length && /[A-Za-z0-9]/.test(src[j])) j++
      tokens.push({ type: 'IDENT', value: src.slice(i, j) })
      i = j
      continue
    }
    const two = src.slice(i, i + 2)
    if (TWO_CHAR_OPS.includes(two)) {
      tokens.push({ type: 'OP', value: two })
      i += 2
      continue
    }
    if (ONE_CHAR_OPS.includes(c)) {
      tokens.push({ type: 'OP', value: c })
      i++
      continue
    }
    throw new Error(`unexpected character ${c}`)
  }
  tokens.push({ type: 'EOF' })
  return tokens
}

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.tokens[this.pos]
  }

  next() {
    return this.tokens[this.pos++]
  }

  expectOp(value) {
    const t = this.peek()
    if (t.type !== 'OP' || t.value !== value) throw new Error(`expected ${value}`)
    this.next()
  }

  parseExpr() {
    return this.parseComparison()
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.peek().type === 'OP' && COMPARISON_OPS.has(this.peek().value)) {
      const op = this.next().value
      const right = this.parseAdditive()
      left = { type: 'BinOp', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.peek().type === 'OP' && (this.peek().value === '+' || this.peek().value === '-')) {
      const op = this.next().value
      const right = this.parseMultiplicative()
      left = { type: 'BinOp', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.peek().type === 'OP' && (this.peek().value === '*' || this.peek().value === '/')) {
      const op = this.next().value
      const right = this.parsePower()
      left = { type: 'BinOp', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.peek().type === 'OP' && this.peek().value === '^') {
      this.next()
      const right = this.parsePower()
      return { type: 'BinOp', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.peek().type === 'OP' && (this.peek().value === '-' || this.peek().value === '+')) {
      const op = this.next().value
      const operand = this.parseUnary()
      return { type: 'UnaryOp', op, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (t.type === 'NUM') {
      this.next()
      return { type: 'Num', value: t.value }
    }
    if (t.type === 'OP' && t.value === '(') {
      this.next()
      const inner = this.parseExpr()
      this.expectOp(')')
      return { type: 'Paren', inner }
    }
    if (t.type === 'IDENT') {
      this.next()
      const name = t.value
      if (this.peek().type === 'OP' && this.peek().value === '(') {
        this.next()
        const args = this.parseArgList()
        this.expectOp(')')
        return { type: 'Call', name, args }
      }
      const upper = name.toUpperCase()
      if (upper === 'TRUE') return { type: 'Bool', value: true }
      if (upper === 'FALSE') return { type: 'Bool', value: false }
      if (this.peek().type === 'OP' && this.peek().value === ':') {
        this.next()
        const to = this.peek()
        if (to.type !== 'IDENT') throw new Error('expected address after :')
        this.next()
        return { type: 'Range', from: name, to: to.value }
      }
      return { type: 'Address', token: name }
    }
    throw new Error('unexpected token')
  }

  parseArgList() {
    const args = [this.parseExpr()]
    while (this.peek().type === 'OP' && this.peek().value === ',') {
      this.next()
      args.push(this.parseExpr())
    }
    return args
  }
}

/**
 * Parses a formula body (the text after `=`). Returns the AST, or `null` if
 * the text is not accepted by the grammar.
 */
export function parseFormula(src) {
  try {
    const tokens = tokenize(src)
    const parser = new Parser(tokens)
    const ast = parser.parseExpr()
    if (parser.peek().type !== 'EOF') return null
    return ast
  } catch {
    return null
  }
}
"}

