{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-Gem8ib/src/values.js","content":"/**
 * The tagged value type every cell evaluates to (`number`, `text`, `bool` or
 * `error`), and the literal-content reader.
 */

const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const NUMBER_RE = /^-?[0-9]+(\.[0-9]+)?$/

export function mkNum(value) {
  return { kind: 'number', value }
}
export function mkText(value) {
  return { kind: 'text', value }
}
export function mkBool(value) {
  return { kind: 'bool', value }
}
export function mkErr(value) {
  return { kind: 'error', value }
}

/** Reads a non-formula cell's verbatim content into its literal value. */
export function parseLiteral(content) {
  if (content === '') return mkNum(0)
  if (ERROR_TOKENS.has(content)) return mkErr(content)
  if (NUMBER_RE.test(content)) return mkNum(Number(content))
  return mkText(content)
}

/** Coerces a non-error value to a plain number, or returns `null` for text. */
export function coerceNumber(value) {
  if (value.kind === 'number') return value.value
  if (value.kind === 'bool') return value.value ? 1 : 0
  return null
}

/** A finite number becomes `mkNum`; anything else becomes `#DIV/0!`. */
export function finiteOrDivErr(n) {
  return Number.isFinite(n) ? mkNum(n) : mkErr('#DIV/0!')
}

const KIND_RANK = { number: 0, text: 1, bool: 2 }

/** Three-way comparator across numbers, text and booleans per the spec's ordering. */
export function compareValues(a, b) {
  if (a.kind !== b.kind) return KIND_RANK[a.kind] - KIND_RANK[b.kind]
  if (a.kind === 'number') return a.value - b.value
  if (a.kind === 'text') return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  return (a.value ? 1 : 0) - (b.value ? 1 : 0)
}
"}

