 * Evaluates a compiled sheet's cells to values, resolving cell references
 * lazily and detecting reference cycles as they are found.
 */

import { parseAddressToken, colToLetters } from './address.js'
import { mkNum, mkBool, mkErr, coerceNumber, finiteOrDivErr, compareValues } from './values.js'

const COMPARISON_APPLY = {
  '=': (c) => c === 0,
  '<>': (c) => c !== 0,
  '<': (c) => c < 0,
  '<=': (c) => c <= 0,
  '>': (c) => c > 0,
  '>=': (c) => c >= 0,
}

/**
 * Builds an evaluator bound to a compiled sheet (address key -> `{ literal }`
 * or `{ ast }`, `ast` being `null` for an ungrammatical formula).
 */
export function createEvaluator(compiled) {
  const cache = new Map()
  const visiting = new Set()

  function evaluateCellByKey(key) {
    if (cache.has(key)) return cache.get(key)
    if (!compiled.has(key)) return mkNum(0)
    if (visiting.has(key)) return mkErr('#CYCLE!')
    visiting.add(key)
    const cell = compiled.get(key)
    const result = cell.ast !== undefined ? (cell.ast === null ? mkErr('#ERR!') : evaluate(cell.ast)) : cell.literal
    visiting.delete(key)
    cache.set(key, result)
    return result
  }

  function evalAddress(token) {
    const addr = parseAddressToken(token)
    if (!addr) return mkErr('#REF!')
    return evaluateCellByKey(addr.key)
  }

  function expandRangeValues(node) {
    const from = parseAddressToken(node.from)
    const to = parseAddressToken(node.to)
    if (!from || !to) return [mkErr('#REF!')]
    const minCol = Math.min(from.col, to.col)
    const maxCol = Math.max(from.col, to.col)
    const minRow = Math.min(from.row, to.row)
    const maxRow = Math.max(from.row, to.row)
    const values = []
    for (let col = minCol; col <= maxCol; col++) {
      const letters = colToLetters(col)
      for (let row = minRow; row <= maxRow; row++) {
        values.push(evaluateCellByKey(`${letters}${row}`))
      }
    }
    return values
  }

  function argValues(node) {
    return node.type === 'Range' ? expandRangeValues(node) : [evaluate(node)]
  }

  function firstError(values) {
    for (const v of values) if (v.kind === 'error') return v
    return null
  }

  function evalAggregate(fname, argNodes) {
    const values = []
    for (const a of argNodes) values.push(...argValues(a))
    const err = firstError(values)
    if (err) return err
    if (fname === 'COUNT') return mkNum(values.filter((v) => v.kind === 'number').length)
    const nums = []
    for (const v of values) {
      const n = coerceNumber(v)
      if (n === null) return mkErr('#VALUE!')
      nums.push(n)
    }
    if (fname === 'SUM') return finiteOrDivErr(nums.reduce((a, b) => a + b, 0))
    if (fname === 'AVG') return finiteOrDivErr(nums.reduce((a, b) => a + b, 0) / nums.length)
    if (fname === 'MIN') return finiteOrDivErr(Math.min(...nums))
    return finiteOrDivErr(Math.max(...nums))
