 * Walks a formula AST to collect every distinct in-range cell it names
 * directly, ranges expanded, ordered by column then row.
 */

import { parseAddressToken, colToLetters, compareAddress } from './address.js'

function addAddress(set, token) {
  const addr = parseAddressToken(token)
  if (addr) set.set(addr.key, addr)
}

function addRange(set, from, to) {
  const a = parseAddressToken(from)
  const b = parseAddressToken(to)
  if (!a || !b) return
  const minCol = Math.min(a.col, b.col)
  const maxCol = Math.max(a.col, b.col)
  const minRow = Math.min(a.row, b.row)
  const maxRow = Math.max(a.row, b.row)
  for (let col = minCol; col <= maxCol; col++) {
    const letters = colToLetters(col)
    for (let row = minRow; row <= maxRow; row++) {
      set.set(`${letters}${row}`, { col, row, key: `${letters}${row}` })
    }
  }
}

function walk(node, set) {
  switch (node.type) {
    case 'Address':
      addAddress(set, node.token)
