/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheetParser.js'
import { parseFormula } from './formula.js'
import { parseLiteral } from './values.js'
import { createEvaluator } from './evaluate.js'
import { collectDeps } from './deps.js'
import { formatValue } from './format.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
    fail('usage: cli.js values|deps')
  }

  const input = readFileSync(0, 'utf8')

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) fail(e.message)
    throw e
  }

  const order = [...cells.entries()].sort((a, b) => a[1].addr.col - b[1].addr.col || a[1].addr.row - b[1].addr.row)

  const compiled = new Map()
  for (const [key, { content }] of cells) {
    if (content.startsWith('=')) {
      compiled.set(key, { ast: parseFormula(content.slice(1)) })
    } else {
      compiled.set(key, { literal: parseLiteral(content) })
    }
  }

  const lines = []
  if (mode === 'values') {
    const { evaluateCellByKey } = createEvaluator(compiled)
    for (const [key] of order) {
      lines.push(`${key}=${formatValue(evaluateCellByKey(key))}`)
    }
  } else {
    for (const [key] of order) {
      const cell = compiled.get(key)
      const deps = cell.ast ? collectDeps(cell.ast) : []
      lines.push(deps.length ? `${key}: ${deps.join(' ')}` : `${key}:`)
    }
  }

  process.stdout.write(lines.length ? lines.join('\n') + '\n' : '')
}

main()
"}

